// === Tab: mySketch ===
// For the #WCCChallenge, Theme: "Psychedelic" --- March 2026
// https://www.youtube.com/shorts/vWPBY6l_BsY

var t = 0;

var rings = 60;    // Anzahl radialer Schichten
var points =60;    // Punkte pro Ring

var baseRadius = 35;
var ringGap = 4.8;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  background(0);
  smooth();
}

function draw() {
  background(0,40);

  translate(width / 2, height / 2);

  blendMode(ADD);

  for (let k = 0; k < 3; k++) {
    drawMandalaLayer(k);
  }

  blendMode(BLEND);

  drawCenterGlow();

  t += 0.012+0.006*sin(PI/300*frameCount);
}

function drawMandalaLayer(layer) {
  let layerShift = layer * TWO_PI / 3.0;
  let hueBase = (frameCount * 0.8 + layer * 90) % 360;

  for (let i = 0; i < rings; i++) {
    let rn = i / (rings - 1);

    let breath =
      1.0 +
      0.16 * sin(t * 2.0 + rn * 5.0 + layerShift) +
      0.05 * sin(t * 5.0 - rn * 9.0);

    let spiralTwist =
      1.2 * rn * TWO_PI +
      0.45 * sin(t * 1.3 + rn * 8.0 + layerShift);

    let radius = (baseRadius + i * ringGap) * breath;

    let sw = 1.8 - 1.2 * rn;
    strokeWeight(max(0.35, sw));

    noFill();
    beginShape();

    for (let j = 0; j <= points; j++) {
      let a = TWO_PI * j / points;

      let wave1 = 18 * sin(4 * a + t * 1.8 + rn * 10 + layerShift);
      let wave2 = 8 * sin(9 * a - t * 2.4 - rn * 7);
      let wave3 = 5 * cos(14 * a + t * 1.1 + layerShift);

      let rr = radius + wave1 + wave2 + wave3;

      let aa =
        a + spiralTwist +
        0.12 * sin(6 * a + t * 1.7 + rn * 12);

      let x = rr * cos(aa);
      let y = rr * sin(aa);

      let hh = (hueBase + 120 * rn + 25 * sin(a * 3 + t * 2)) % 360;
      stroke(hh, 80, 100, 40);

      vertex(x, y);
    }

    endShape(CLOSE);

    // kleine Leuchtpunkte
    let dots = 18;
    noStroke();
    for (let d = 0; d < dots; d++) {
      var a = TWO_PI * d / dots + spiralTwist * 0.8;
      var rr =
        radius +
        12 * sin(5 * a + t * 1.5 + rn * 8) +
        6 * cos(7 * a - t * 1.2);

      var x = rr * cos(a);
      var y = rr * sin(a);

      fill((hueBase + 180 * rn + d * 8) % 360, 70, 100, 35);
      circle(x, y, 2.5 + 3.5 * (1 - rn));
    }
  }
}

function drawCenterGlow() {
  noStroke();

  for (let i = 22; i >= 1; i--) {
    let r =
      i * 6.0 +
      8 * sin(t * 2.5 + i * 0.25);

    fill((frameCount * 1.5 + i * 6) % 360, 60, 100, 8);
    circle(0, 0, r);
  }

  fill(0, 0, 100, 85);
  circle(0, 0, 18);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
